#include <stdlib.h>

struct N { int key, h; struct N *l, *r; };

static int ht(const struct N *n) { return n ? n->h : 0; }
static int mx(int a, int b) { return a > b ? a : b; }
static void upd(struct N *n) { n->h = 1 + mx(ht(n->l), ht(n->r)); }
static int bal(const struct N *n) { return n ? ht(n->l) - ht(n->r) : 0; }

static struct N *rot_right(struct N *y) {   /* y is the heavy node */
    struct N *x = y->l;
    y->l = x->r;
    x->r = y;
    upd(y); upd(x);
    return x;                               /* new subtree root */
}

static struct N *rot_left(struct N *x) {
    struct N *y = x->r;
    x->r = y->l;
    y->l = x;
    upd(x); upd(y);
    return y;
}

static struct N *rebalance(struct N *n) {
    upd(n);
    int b = bal(n);
    if (b > 1) {                            /* left heavy */
        if (bal(n->l) < 0) n->l = rot_left(n->l);   /* LR */
        return rot_right(n);                         /* LL */
    }
    if (b < -1) {                           /* right heavy */
        if (bal(n->r) > 0) n->r = rot_right(n->r);  /* RL */
        return rot_left(n);                          /* RR */
    }
    return n;
}

struct N *avl_insert(struct N *n, int k) {
    if (!n) {
        struct N *t = calloc(1, sizeof *t);
        if (!t) abort();
        t->key = k; t->h = 1;
        return t;
    }
    if (k < n->key)      n->l = avl_insert(n->l, k);
    else if (k > n->key) n->r = avl_insert(n->r, k);
    else return n;                          /* ignore duplicates */
    return rebalance(n);
}

struct N *avl_delete(struct N *n, int k) {
    if (!n) return NULL;
    if (k < n->key)      n->l = avl_delete(n->l, k);
    else if (k > n->key) n->r = avl_delete(n->r, k);
    else {
        if (!n->l || !n->r) {
            struct N *c = n->l ? n->l : n->r;
            free(n);
            return c;                       /* may be NULL */
        }
        struct N *s = n->r;
        while (s->l) s = s->l;
        n->key = s->key;
        n->r = avl_delete(n->r, s->key);
    }
    return rebalance(n);
}

/* returns height, or -1000 if invalid */
static int check(const struct N *n, long lo, long hi) {
    if (!n) return 0;
    if (n->key <= lo || n->key >= hi) return -1000;
    int a = check(n->l, lo, n->key), b = check(n->r, n->key, hi);
    if (a < 0 || b < 0 || a - b > 1 || b - a > 1) return -1000;
    if (n->h != 1 + (a > b ? a : b)) return -1000;
    return n->h;
}
